"""The rule tables in RULES.md match the YAML rules (generated by `rules list --markdown`)."""

from pathlib import Path

import pytest

from helpers import builtin_rules
from repovet.cli import EXIT_OK, main

RULES = Path(__file__).parent.parent / "RULES.md"
START = "<!-- rules-table:start -->"
END = "<!-- rules-table:end -->"


def test_rule_tables_are_current(capsys: pytest.CaptureFixture[str]) -> None:
    assert main(["rules", "list", "--markdown"]) == EXIT_OK
    generated = capsys.readouterr().out
    text = RULES.read_text(encoding="utf-8")
    assert text.count(START) == 1
    assert text.count(END) == 1
    table = text.split(START)[1].split(END)[0]
    assert table.strip() == generated.strip(), (
        "RULES.md is out of date; regenerate the tables with `uv run repovet rules list --markdown`"
    )


def test_markdown_lists_every_rule_once(capsys: pytest.CaptureFixture[str]) -> None:
    main(["rules", "list", "--markdown"])
    rows = [line for line in capsys.readouterr().out.splitlines() if line.startswith("| RC-")]
    assert sorted(row.split(" | ")[0][2:] for row in rows) == sorted(
        rule.id for rule in builtin_rules().rules
    )
    main(["rules", "list", "--markdown", "--area", "agents"])
    out = capsys.readouterr().out
    assert "RC-AGENT-001" in out
    assert "RC-AUTO-" not in out
